var poolSmall = sync.Pool{New: func() any {
	b := make([]byte, 0, 64)
	return &b
}}

func fill(buf []byte) []byte {
	buf = buf[:0]
	for i := 0; i < 1_000_000; i++ {
		buf = append(buf, 'a')
	}
	return buf
}

func useFill() int {
	bp := poolSmall.Get().(*[]byte)
	buf := fill(*bp)
	n := len(buf)
	poolSmall.Put(bp)
	return n
}
